#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    /// <summary>
    /// 颠倒炸弹：类 TNT 器械，被点燃后倒计时爆炸。
    /// - 普通引爆（火把点燃等）：600 点爆炸伤害（照 TNT，仅对敌方生效），
    ///   随后对爆炸范围内的单位施加效果：器械获得 7 秒颠倒，苦力怕获得高压（不触发真名解放）。
    /// - 星之碎片能力引爆（evoke 点燃自己）：爆炸效果替换为全场版本——不造成伤害，
    ///   全场器械获得 7 秒颠倒，清除所有敌方苦力怕的高压，全场苦力怕获得 30 秒绝缘。
    /// - 施加的颠倒与高压效果不分敌我。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.reverseBomb)]
    public class ReverseBomb : ContraptionBehaviour, IExplodeContraptionBehaviour
    {
        public ReverseBomb(string nsp, string name) : base(nsp, name)
        {
        }

        void IExplodeContraptionBehaviour.Explode(Entity entity, float range, float damage)
        {
            if (entity.IsEvoked())
            {
                // 星之碎片引爆：爆炸效果替换为全场版本，不造成伤害
                StarDetonate(entity);
            }
            else
            {
                NormalBlast(entity, range, damage);
            }
        }

        // 普通引爆：600 点爆炸伤害仅对敌方，随后对范围内不分敌我施加颠倒/高压
        private static void NormalBlast(Entity entity, float range, float damage)
        {
            var damageEffects = new DamageEffectList(
                VanillaDamageEffects.MUTE,
                VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN,
                VanillaDamageEffects.EXPLOSION
            );
            entity.Explode(entity.Position, range, entity.GetFaction(), damage, damageEffects);

            BlastEffects(entity, range);

            Explosion.Spawn(entity, entity.GetCenter(), range);
            entity.PlaySound(VanillaSoundID.explosion);
            entity.Level.ShakeScreen(10, 0, 15);
        }

        // 星之碎片引爆：全场器械颠倒、清除敌方苦力怕高压、全场苦力怕绝缘，不造成伤害
        private static void StarDetonate(Entity entity)
        {
            var level = entity.Level;
            foreach (var plant in level.FindEntities(e => e.Type == EntityTypes.PLANT))
            {
                ContraptionInvertedBuff.Apply(plant, INVERT_SECONDS);
            }
            foreach (var enemy in level.FindEntities(e => e.Type == EntityTypes.ENEMY && e.IsHostileEntity()))
            {
                if (enemy.HasBehaviour<Creeper>())
                {
                    enemy.RemoveBuffs<CreeperChargedBuff>();
                }
            }
            foreach (var enemy in level.FindEntities(e => e.Type == EntityTypes.ENEMY && e.HasBehaviour<Creeper>()))
            {
                InsulatedBuff.Apply(enemy, INSULATED_SECONDS);
            }

            Explosion.Spawn(entity, entity.GetCenter(), entity.GetRange());
            entity.PlaySound(VanillaSoundID.explosion);
            entity.Level.ShakeScreen(10, 0, 15);
        }

        // 范围内不分敌我施加效果：器械颠倒、苦力怕高压（不触发真名解放）
        private static void BlastEffects(Entity entity, float range)
        {
            var targets = new List<Entity>();
            var detector = new SphereDetector(range)
            {
                factionTarget = FactionTarget.Any,
                mask = EntityCollisionHelper.MASK_PLANT | EntityCollisionHelper.MASK_ENEMY,
                canDetectInvisible = true
            };
            detector.DetectEntities(entity, targets);
            foreach (var target in targets)
            {
                if (target.Type == EntityTypes.PLANT)
                {
                    ContraptionInvertedBuff.Apply(target, INVERT_SECONDS);
                }
                else if (target.Type == EntityTypes.ENEMY && target.HasBehaviour<Creeper>())
                {
                    if (!target.HasBuff<CreeperChargedBuff>())
                    {
                        target.AddBuff<CreeperChargedBuff>();
                    }
                }
            }
        }

        private const float INVERT_SECONDS = 7f;
        private const float INSULATED_SECONDS = 30f;
    }
}
